public static Callable<BooleanSupplier> prepareXml(@NonNull Live item, OkHttpClient client) {
    List<String> urls = List.copyOf(item.getEpgXml());
    EpgParser.XmlTarget target = EpgParser.snapshot(item);
    return () -> {
        List<Runnable> updates = new ArrayList<>();
        for (String url : urls) {
            if (Thread.currentThread().isInterrupted()) break;
            try {
                updates.add(EpgParser.prepare(target, url, client, client == null ? url : METADATA_TAG));
            } catch (Exception e) {
                e.printStackTrace();
            }
        }
        return () -> {
            boolean parsed = false;
            for (Runnable update : updates) {
                try {
                    update.run();
                    parsed = true;
                } catch (Exception e) {
                    e.printStackTrace();
                }
            }
            return parsed;
        };
    };
}

