public static Callable<Supplier<Epg>> prepareEpg(@NonNull Channel item, @NonNull ZoneId zoneId, OkHttpClient client) {
    String template = item.getEpg();
    String key = item.getTvgId();
    LocalDate today = LocalDate.now(zoneId);
    Set<String> cached = new HashSet<>();
    item.getDataList().forEach(epg -> cached.add(epg.getDate()));
    return () -> {
        List<Epg> updates = new ArrayList<>();
        for (int offset = -1; offset <= 1; offset++) {
            if (Thread.currentThread().isInterrupted()) break;
            String date = today.plusDays(offset).format(Formatters.DATE);
            String url = template.replace("{date}", date);
            if (!url.startsWith("http") || cached.contains(date)) continue;
            Epg day = readEpgDay(url, key, date, zoneId, client);
            if (day == null) continue;
            updates.add(day);
            cached.add(day.getDate());
        }
        return () -> {
            // An authorized XML refresh may have filled this day meanwhile.
            for (Epg day : updates) {
                if (item.getDataList().stream().noneMatch(epg -> epg.equal(day.getDate()))) item.setData(day);
            }
            return item.getData(zoneId).selected();
        };
    };
}

